sys_script_include.script:
var AppointmentUtils = Class.create();
AppointmentUtils.prototype = {
    initialize: function() {
    },
     getAppointmentsByPatient: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_appointment_table');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_number') + ';' + gr.getValue('u_appointment_date') + ';' + gr.getValue('u_department') + '\n';
        }
        return result || false;
    },

    // 2. Check if an appointment is confirmed
    isAppointmentConfirmed: function (appointmentNumber) {
        var gr = new GlideRecord('u_appointment_table');
        gr.addQuery('u_number', appointmentNumber);
        gr.query();
        if (gr.next()) {
            return gr.getDisplayValue('state') === 'Confirmed';
        }
        return false;
    },

    // 3. Fetch appointment details by ID
    getAppointmentDetailsById: function (appointmentNumber) {
        var gr = new GlideRecord('u_appointment_table');
        gr.addQuery('u_number', appointmentNumber);
        gr.query();
        if (gr.next()) {
            return gr.getValue('u_number') + ';' + gr.getValue('u_appointment_date') + ';' + gr.getValue('u_department') + ';' + gr.getDisplayValue('u_patient_id');
        }
        return false;
    },

    // 4. Fetch appointments by date
    getAppointmentsByDate: function (date) {
        var result = '';
        var gr = new GlideRecord('u_appointment_table');
        gr.addQuery('u_appointment_date', 'STARTSWITH', date); // e.g., '2025-07-08'
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_number') + ';' + gr.getDisplayValue('u_patient_id') + ';' + gr.getValue('u_department') + '\n';
        }
        return result || false;
    },

    // 5. Fetch appointments by department
    getAppointmentsByDepartment: function (department) {
        var result = '';
        var gr = new GlideRecord('u_appointment_table');
        gr.addQuery('u_department', department);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_number') + ';' + gr.getValue('u_appointment_date') + ';' + gr.getDisplayValue('state') + '\n';
        }
        return result || false;
    },
    type: 'AppointmentUtils'
};
